insert into public.listings (name, category, area, description, address, postcode, lat, lng, website, opening_hours, price_band, ages, status, claimed, featured) values
('Blaise Castle Estate', 'outdoors', 'North Bristol', 'A huge estate in north-west Bristol with woodland, a folly castle and one of the city''s best play areas, split into fenced, dog-free zones for younger and older children. The younger play area has sand play, swings and a slide next to the café and toilets.', 'Kings Weston Road, Kings Weston', 'BS10 7QT', 51.5026, -2.6373, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/blaise-castle-estate', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false),
('Hengrove Play Park', 'outdoors', 'South Bristol', 'Bristol''s biggest free play park: four acres with a 12-metre jungle dome, sand and water play for little ones, zones for older children and a wheels park for scooters and BMX. Café on site and free parking. Check opening times before you go, as they change with the seasons.', 'Hengrove Way, Hengrove', 'BS14 0HR', 51.414, -2.582, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/hengrove-park', 'Seasonal opening times, see council website', 0, array['toddler','kids','teen']::text[], 'draft', true, false),
('Oldbury Court Estate', 'outdoors', 'East Bristol', 'Historic parkland in Fishponds with woodland and riverside walks along the Frome towards Snuff Mills, and a play area that reopened in 2026 after a major renovation. Two car parks.', 'Oldbury Court Road, Fishponds', 'BS16 2QX', 51.48889, -2.52694, 'https://www.bristol.gov.uk/museums-parks-sports-culture/oldbury-court-estate', 'Always open, car parks 8am to dusk', 0, array['toddler','kids']::text[], 'draft', true, false),
('Ashton Court Estate', 'outdoors', 'South Bristol', 'A vast estate on the edge of the city with woodland walks, wide open grassland and big views. Brilliant for a picnic, a ramble or a bike ride. Toilets at the mansion; the car parks are paid.', 'Long Ashton', 'BS41 9JN', 51.4479, -2.6446, 'https://www.bristol.gov.uk/museums-parks-sports-culture/ashton-court-estate', 'Open daily from 8am', 0, array['baby','toddler','kids','teen']::text[], 'draft', true, false),
('St George Park', 'outdoors', 'East Bristol', 'One of Bristol''s finest Victorian parks, with a lake, mature trees and a large, popular play area including an accessible roundabout, an in-ground trampoline and swings. Car park on Chalks Road.', 'Chalks Road, St George', 'BS5 8AA', 51.4618, -2.5479, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates', 'Open 24 hours', 0, array['toddler','kids']::text[], 'draft', true, false),
('Victoria Park', 'outdoors', 'South Bristol', 'A big Victorian park on Windmill Hill with city views, a water maze, skate park and a fenced, dog-free adventure play area with aerial walkways, rope bridges and nets. The play area is on a slope, so it''s tricky for wheelchairs.', 'Hill Avenue, Bedminster', 'BS3 4DP', 51.44084, -2.5869, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/victoria-park', 'Always open', 0, array['toddler','kids','teen']::text[], 'draft', true, false),
('Eastville Park', 'outdoors', 'East Bristol', 'A large Victorian park with two playgrounds (swings for toddlers in the lower one, a big sand pit in the upper one), a fishing lake and plenty of green space. Junior parkrun every Sunday morning.', 'Fishponds Road, Eastville', 'BS5 6XA', 51.4757, -2.5585, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/eastville-park', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false),
('Canford Park', 'outdoors', 'North Bristol', 'A pretty Victorian park with a large, dog-free playground for under-12s, plus a café, tennis courts and ponds. Tarmac paths make it easy with buggies and wheelchairs. No car park, but there''s usually street parking nearby.', 'Canford Lane, Westbury-on-Trym', 'BS9 3PD', 51.493399, -2.626131, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/canford-park', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false),
('St Andrews Park', 'outdoors', 'North Bristol', 'A classic Victorian neighbourhood park with a dog-free play area and a big paddling pool that''s a magnet for families on hot summer days. Tarmac paths throughout, with some slopes.', 'Effingham Road, St Andrews', 'BS6 5AZ', null, null, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/st-andrews-park', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false),
('Brandon Hill', 'outdoors', 'Central Bristol', 'Bristol''s oldest park, right by Park Street, with a dog-free play area for under-12s at the bottom of the hill, a nature park and views from Cabot Tower at the top. Toilets near the tower.', 'Park Street', 'BS1 5RR', null, null, 'https://www.bristol.gov.uk/museums-parks-sports-culture/brandon-hill', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false),
('Gores Marsh Park', 'outdoors', 'South Bristol', 'A flat, accessible park near Ashton Gate with a nature-themed play area: look-out mounds, stepping stones, a rope swing and a dish roundabout.', 'Winterstoke Road, Ashton Gate', 'BS3 2LP', null, null, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-with-play-equipment', 'Open 24 hours', 0, array['toddler','kids']::text[], 'draft', true, false),
('Dundridge Park', 'outdoors', 'East Bristol', 'A large community park in St George with a children''s playground and football pitches.', 'Dundridge Lane, St George', 'BS5 8SW', null, null, 'https://www.bristol.gov.uk/residents/museums-parks-sports-and-culture/parks-and-open-spaces/parks-and-estates/dundridge-park', 'Always open', 0, array['toddler','kids']::text[], 'draft', true, false);
